    override fun onAttach(context: Context) {
        super.onAttach(context)
        callback = context as? CallBack
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        val tracker: Tracker? = App.getTracker()
        TrackHelper.track().screen("coffeeinventory/ui/VegaCoffeeInventoryListFragment").title("IVC/Coffee/Inventory/List")
            .with(tracker)

        binding.tvTruckNo.text = resources.getString(R.string.inventory_list)
        binding.tvFilter.setOnClickListener {

            val positions: List<Int> = wareHouseList.withIndex().filter { it.value.isExpanded }.map { it.index }
            if (positions.isNotEmpty()) {
                expandPosition = positions[0]
            }
            moveToFilter(kors, origins)
        }
        vm.product.observe(viewLifecycleOwner, Observer {
            materialList = it as MutableList<VegaMaterial>
            vm.getInventoryList()
        })
        vm.getProducts()
        vm.inventoryModelList.observe(viewLifecycleOwner, Observer { updateUI(it) })
        binding.cvLotDetails.gone()
        binding.tvSort.setOnClickListener {
            isDescends = !isDescends
            sortByWeight(vm.inventoryModelList.value?.data?.data?.inventories ?: ArrayList())
        }

        binding.tvSearchLot.setOnClickListener {
            MaterialDialog(requireContext()).show {
                title(R.string.search_lot_number)
                var lotNo = ""
                input(
                    waitForPositiveButton = false,
                    hint = getString(R.string.enter_lot_no)
                ) { dialog, text ->
                    val inputField = dialog.getInputField()
                    val isValid = text.isNotEmpty()
                    lotNo = text.toString()
                    inputField.error = if (isValid) null else getString(R.string.enter_lot_no)
                    dialog.setActionButtonEnabled(WhichButton.POSITIVE, isValid)
                }
                UIUtils.getMetirialCustomView(
                    this,
                    getString(com.olam.warehouse.presentation.R.string.confirm),
                    getString(com.olam.warehouse.presentation.R.string.cancel),
                    {
                        val bundle = Bundle().apply {
                            putString("LOTID", lotNo)
                        }
                        callback?.replaceFragment("details", bundle)
                    },
                    { dismiss() })
            }
        }
    }


    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setHasOptionsMenu(true)
    }


    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View? {
        setHasOptionsMenu(true)
        /* val gson = Gson()
         val vegaInventoryAndSyncModel = gson.fromJson(data, VegaCoffeeInventoryAndSyncModel::class.java)
         if (vegaInventoryAndSyncModel != null) {
             wareHouseList = vegaInventoryAndSyncModel.inventories as ArrayList<VegaCoffeeInventoryWarehouseModel>
             syncStatusList = vegaInventoryAndSyncModel.syncStatus as ArrayList<CoffeeSyncStatus>
         }*/
        binding = FragmentVegaCoffeeInventoryListBinding.inflate(layoutInflater)
        return binding.root
    }

    override fun onCreateOptionsMenu(menu: Menu, inflater: MenuInflater) {
        super.onCreateOptionsMenu(menu, inflater)
        activity?.menuInflater?.inflate(com.olam.warehouse.presentation.R.menu.search_menu, menu)
        try {
            val search = menu.findItem(com.olam.warehouse.presentation.R.id.search)
            val searchView: SearchView =
                search?.actionView as SearchView
            searchView.setBackgroundColor(
                ContextCompat.getColor(
                    searchView.context,
                    com.olam.warehouse.presentation.R.color.colorPrimaryOfi
                )
            )
            searchView.queryHint = getString(R.string.search_wh)
            getAllFilterValues()
            setAdapter(wareHouseList)
            //syncDetails()
            searchView.setOnQueryTextListener(object : SearchView.OnQueryTextListener {
                override fun onQueryTextSubmit(query: String?): Boolean {
                    return false
                }

                override fun onQueryTextChange(newText: String?): Boolean {
                    newText.let {
                        if (newText?.isEmpty() == true) {
                            setAdapter(wareHouseList)
                        } else {
                            mSearchList.clear()
                            wareHouseList.forEach { qtyWb ->
                                newText?.let { text ->
                                    if (qtyWb.warehouse.warehouseName!!.contains(text, true)) {
                                        mSearchList.add(qtyWb)
                                    }
                                }
                            }
                            setAdapter(mSearchList)
                        }
                    }
                    return true
                }
            })
        } catch (e: ClassCastException) {
            e.printStackTrace()
        }
    }

    companion object {
        const val SEARCH_HINT_TEXT = "Search warehouse"
    }

    private fun setAdapter(data: List<VegaCoffeeInventoryWarehouseModel>) {
        binding.rvWeighBridgeId.layoutManager = LinearLayoutManager(activity).apply { LinearLayoutManager.VERTICAL }
        binding.rvWeighBridgeId.adapter = VegaInventoryParentAdapter(data, materialList, this)
    }

    private fun getAllFilterValues() {
        for (item in wareHouseList) {
            for (sub in item.storageLoc) {
                for (kor in sub.averageKors)
                    kors.add(kor)
            }
        }
        for (item in wareHouseList) {
            for (sub in item.storageLoc) {
                for (origin in sub.origins)
                    origins.add(origin)
            }
        }
    }

    var kors = ArrayList<String>()
    var origins = ArrayList<String>()


    override fun navigateToDetails(storage: CoffeeStorageLoc, colorCode: Int) {
        val bundle = Bundle().apply {
            putSerializable("Lots", storage)
            putInt("code", colorCode)
        }
        callback?.replaceFragment("details", bundle)
    }

    private fun syncDetails() {
        val bottomDialog = VegaCoffeeInventorySyncDetailsDailog.newInstance(syncStatusList)
        activity?.supportFragmentManager?.let { it1 -> bottomDialog.show(it1, "BottomSheet") }
    }


    fun applyFilterValues(
        listKor: ArrayList<String>,
        listOrigin: ArrayList<String>
    ) {

        if (listKor.isEmpty() && listOrigin.isEmpty()) {
            this.fullFilter.clear()
            setAdapter(wareHouseList)
            return
        }
        val fullFilter = ArrayList<String>()
        fullFilter.addAll(listKor)
        fullFilter.addAll(listOrigin)
        this.fullFilter = fullFilter
        val model = ArrayList<VegaCoffeeInventoryWarehouseModel>()
        for (item in wareHouseList) {
            model.add(item.copy())
        }
        val filterData = ArrayList<CoffeeStorageLoc>()
        val filterWarehouse = ArrayList<VegaCoffeeInventoryWarehouseModel>()

        model.forEachIndexed { index, mod ->
            fullFilter.forEach { korOrigin ->
                mod.storageLoc.forEach { storage ->
                    storage.averageKors.let {
                        if (storage.averageKors.contains(korOrigin) || storage.origin?.contains(korOrigin)!!) {
                            filterData.add(storage)
                        }
                    }
                }
            }
            if (filterData.isNotEmpty()) {
                @Suppress("UNCHECKED_CAST")
                val storageFilter = filterData.clone() as ArrayList<CoffeeStorageLoc>
                val modd = model[index]
                modd.storageLoc = storageFilter
                filterWarehouse.add(modd)
                filterData.clear()
            }
        }

        val result = HashSet<VegaCoffeeInventoryWarehouseModel>()
        result.addAll(filterWarehouse)
        val warehouse = result.toList()

        for (item in warehouse) {
            item.storageLoc = removeDuplicates(item)
        }
        setAdapter(warehouse)
    }

    private fun removeDuplicates(warehouse: VegaCoffeeInventoryWarehouseModel): List<CoffeeStorageLoc> {
        val result = HashSet<CoffeeStorageLoc>()
        result.addAll(warehouse.storageLoc)
        return result.toList()
    }

    private fun moveToFilter(korList: ArrayList<String>, orgins: ArrayList<String>) {
        val bundle = Bundle().apply {
            putStringArrayList("kors", korList)
            putStringArrayList("origins", orgins)
        }
        callback?.replaceFragment("", bundle, fullFilter)
    }

    private fun sortByWeight(list: List<VegaCoffeeInventoryWarehouseModel>) {
        val sortedList: List<VegaCoffeeInventoryWarehouseModel>
        if (isDescends) {
            sortedList = list.sortedByDescending { wareHouse -> wareHouse.weight.toFloat() }
        } else {
            sortedList = list.sortedBy { wareHouse -> wareHouse.weight.toFloat() }
        }
        setAdapter(sortedList)
    }

    private fun updateUI(data: Resource<GenericReqAndResp<VegaCoffeeInventoryAndSyncModel>>) {
        data.let {
            when (it.status) {
                Resource.Status.SUCCESS -> {
                    hideLoading()
                    wareHouseList = it.data?.data?.inventories as ArrayList<VegaCoffeeInventoryWarehouseModel>
                    syncStatusList = it.data?.data?.syncStatus as ArrayList<CoffeeSyncStatus>
                    getAllFilterValues()
                    setAdapter(it.data?.data?.inventories ?: ArrayList())
                    syncDetails()
                }
                Resource.Status.LOADING -> {
                    showLoading()
                }
                Resource.Status.ERROR -> {
                    showErrorDialogWithFAQLink(requireContext(), it.error.toString())
                    hideLoading()
                }
                else -> {

                }

            }
        }
    }


}
